%c - Single character
%d or %i - Signed decimal integer
%f - Floating-point number (float)
%lf - Double-precision floating-point number (double)
%Lf - Long double-precision floating-point number
%s - String of characters (null-terminated)
%p - Pointer address (in hexadecimal)
%x or %X - Hexadecimal integer (lowercase/uppercase)
%o - Octal integer
%u - Unsigned decimal integer




Specifier	Used For	          Example (printf)	  Example (scanf)
%c	        Single character	  printf("%c", 'A');	  scanf("%c", &ch);
%d/%i	        Signed integer	          printf("%d", -42);	  scanf("%d", &num);
%f	        Float	                  printf("%f", 3.14);	  scanf("%f", &f);
%lf	        Double	                  printf("%lf", 3.14);    scanf("%lf", &d);
%Lf	        Long double	          printf("%Lf", 3.14);	  scanf("%Lf", &ld);
%s	        String	                  printf("%s", str);	  scanf("%s", str);
%p	        Pointer address	          printf("%p", &x);	  -
%x/%X	        Hexadecimal integer	  printf("%x", 255);	  scanf("%x", &hex);
%o	        Octal integer	          printf("%o", 64);	  scanf("%o", &oct);
%u	        Unsigned integer	  printf("%u", 100);	  scanf("%u", &unum);

consoleBlock.c:
#include <stdio.h>

int main() {
    /* ========== %c - Single character ========== */
    // Purpose: Read/print a single character
    char c;
    printf("Enter a character: ");
    scanf("%c", &c);       // Input: 'A'
    printf("You entered: %c\n\n", c);  // Output: 'A'

    /* ========== %d/%i - Signed integer ========== */
    // Purpose: Read/print signed decimal integer
    int num;
    printf("Enter an integer: ");
    scanf("%d", &num);     // Input: -42
    printf("Decimal: %d, Integer format: %i\n\n", num, num);  // Output: -42, -42

    /* ========== %f - Float ========== */
    // Purpose: Read/print floating-point number
    float f;
    printf("Enter a float: ");
    scanf("%f", &f);       // Input: 3.14
    printf("Float: %f\n\n", f);  // Output: 3.140000

    /* ========== %lf - Double ========== */
    // Purpose: Read/print double-precision floating-point
    double d;
    printf("Enter a double: ");
    scanf("%lf", &d);      // Input: 3.1415926535
    printf("Double: %lf\n\n", d);  // Output: 3.141593

    /* ========== %s - String ========== */
    // Purpose: Read/print null-terminated string
    char str[20];
    printf("Enter a string: ");
    scanf("%s", str);      // Input: "Hello"
    printf("String: %s\n\n", str);  // Output: Hello

    /* ========== %p - Pointer ========== */
    // Purpose: Print pointer address
    int x = 10;
    printf("Pointer address: %p\n\n", (void*)&x);  // Output: 0x7ffc...

    /* ========== %x/%X - Hexadecimal ========== */
    // Purpose: Print hexadecimal representation
    printf("Hex (lower): %x\n", 255);  // Output: ff
    printf("Hex (upper): %X\n\n", 255);  // Output: FF

    /* ========== %o - Octal ========== */
    // Purpose: Print octal representation
    printf("Octal: %o\n\n", 64);  // Output: 100

    /* ========== %u - Unsigned integer ========== */
    // Purpose: Print unsigned decimal
    unsigned int u = 4294967295;
    printf("Unsigned: %u\n\n", u);  // Output: 4294967295

    return 0;
}

