    long long ll;
    printf("Enter a long long number: ");
    scanf("%lld", &ll);    // Input: 9223372036854775807
    printf("Long long: %lld\n\n", ll);  // Output: 9223372036854775807

    /* ========== %lu - Unsigned long ========== */
