sections.description:
%e or %E - Scientific notation (lowercase/uppercase 'e')
%g or %G - Uses %e/%E or %f depending on value (shorter representation)
%a or %A - Hexadecimal floating-point (C99)


Specifier	Used For	             Example
%e/%E	        Scientific notation	     printf("%e", 1000.0);
%g/%G	        Auto-choose %f or %e	     printf("%g", 0.0001);
%a/%A	        Hexadecimal float (C99)	     printf("%a", 256.0);

consoleBlock.c:
#include <stdio.h>

int main() {
    /* ========== %e/%E - Scientific notation ========== */
    // Purpose: Print float/double in scientific notation
    double sci = 123456.789;
    printf("Scientific (lower): %e\n", sci);  // Output: 1.234568e+05
    printf("Scientific (upper): %E\n\n", sci);  // Output: 1.234568E+05

    /* ========== %g/%G - Smart float representation ========== */
    // Purpose: Automatically chooses %f or %e/%E for shorter output
    printf("Smart (lower): %g\n", 0.000012345);  // Output: 1.2345e-05
    printf("Smart (upper): %G\n", 123.456);      // Output: 123.456
    printf("Smart (upper): %G\n\n", 123456.789); // Output: 123457

    /* ========== %a/%A - Hexadecimal float ========== */
    // Purpose: Print float/double in hexadecimal scientific notation
    printf("Hex float (lower): %a\n", 256.0);  // Output: 0x1p+8
    printf("Hex float (upper): %A\n\n", 256.0);  // Output: 0X1P+8

    return 0;
}

