int main() {
    /* ========== %n - Character count ========== */
    // Purpose: Stores count of characters printed so far
    int count;
    printf("Hello%n World!\n", &count);
    printf("Characters before %%n: %d\n\n", count);  // Output: 5

    /* ========== %% - Percent sign ========== */
    // Purpose: Print a literal percent character
    printf("Success rate: 100%%\n\n");  // Output: Success rate: 100%

