}

#include <stdio.h>

int main() {
    /* ========== Flags and Width ========== */
    // Left-justify, width 10
    printf("Left-aligned: |%-10s|\n", "Hello");  // Output: |Hello     |

    // Force sign
    printf("Always show sign: %+d\n", 25);       // Output: +25

    // Zero padding, width 5
    printf("Zero-padded: %05d\n", 7);            // Output: 00007

    // Alternate form (hex with 0x)
    printf("Hex with 0x: %#x\n", 15);            // Output: 0xf

    // Floating point with 2 decimal places
    printf("Two decimals: %.2f\n", 3.14159);     // Output: 3.14

    // Scientific notation with width 10, 3 decimal places
    printf("Scientific: %10.3e\n", 1234.56);     // Output:  1.235e+03

    return 0;
}

