    // Derived Data Types (example - array)
    int arrayVar[5] = {1, 2, 3, 4, 5};
    printf("Array Element: %d\n", arrayVar[0]);

    // User-defined data type (example - struct)
    struct MyStruct {
        int member1;
        char member2[20];
    };

    struct MyStruct structVar = {10, "Hello"};
    printf("Struct Member 1: %d\n", structVar.member1);
    printf("Struct Member 2: %s\n", structVar.member2);

